// Prepare the diff and prompt from DevPilot payload
const payload = $json.body || $json;
const diff = payload.diff || '';
const stagedFiles = payload.stagedFiles || [];
const summary = payload.diffSummary || {};
const customPrompt = payload.customPrompt || '';

const fileList = stagedFiles.map(f => `${f.changeType}: ${f.path}`).join('\n');

const prompt = `Analyze the following staged Git changes and generate a commit message strictly adhering to Conventional Commits v1.0.0.

Allowed types: feat, fix, docs, style, refactor, perf, test, build, ci, chore, revert.
Format: <type>(<optional scope>): <description>\n\n[optional body]\n
Staged files:\n${fileList}\n
Diff:\n${diff.slice(0, 8000)}\n
${customPrompt ? 'Additional instructions: ' + customPrompt : ''}`;

return {
  json: {
    prompt,
    payload
  }
};

